#include <stdio.h>

int main(void)
{
int n1, original, reversed = 0;
	scanf("%d", &n1);
	original = n1;
	while (n1 > 0)
{
		reversed = reversed * 10 + n1 % 10;
		n1 /= 10;
	}
	if (reversed == original) printf("Palindrome = YES\n");
	else printf("Palindrome = NO\n");
	return 0;
}

